 return <OrderDetailsView {...props} api={api} print={print} Overlay={Overlay} Badge={Badge} StatusHistory={StatusHistory} updateCache={(updated:Row)=>client.setQueryData(['workspace'],(previous:any)=>previous?{...previous,records:{...previous.records,orders:(previous.records.orders??[]).map((item:Row)=>item.id===updated.id?{...item,...updated}:item)}}:previous)}/>;
